import torch
import torch_npu

def run(x, scale, bias, min_val, max_val):
    return torch.ops.npu.my_pixel_scale_clip(x, float(scale), float(bias), float(min_val), float(max_val))

#include "kernel_operator.h"

using namespace AscendC;

constexpr uint32_t BUFFER_NUM = 2;
constexpr uint32_t ALIGN_NUM = 32;
constexpr uint32_t TILE_LENGTH = 2048;

class KernelPixelScaleClip {
public:
    __aicore__ inline KernelPixelScaleClip() {}
    __aicore__ inline void Init(GM_ADDR x, GM_ADDR y, uint32_t totalLength,
                                float scale, float bias, float minVal, float maxVal)
    {
        this->totalLength = totalLength;
        this->scale = scale;
        this->bias = bias;
        this->minVal = minVal;
        this->maxVal = maxVal;
        xGm.SetGlobalBuffer((__gm__ half *)x, totalLength);
        yGm.SetGlobalBuffer((__gm__ half *)y, totalLength);
        pipe.InitBuffer(inQueueX, BUFFER_NUM, TILE_LENGTH * sizeof(half));
        pipe.InitBuffer(outQueueY, BUFFER_NUM, TILE_LENGTH * sizeof(half));
        pipe.InitBuffer(xFloatBuf, TILE_LENGTH * sizeof(float));
        pipe.InitBuffer(tmpBuf, TILE_LENGTH * sizeof(float));
        pipe.InitBuffer(yFloatBuf, TILE_LENGTH * sizeof(float));
    }
    __aicore__ inline void Process()
    {
        uint32_t blockIdx = GetBlockIdx();
        uint32_t blockNum = GetBlockNum();
        uint32_t elementsPerBlock = (totalLength + blockNum - 1) / blockNum;
        uint32_t startIdx = blockIdx * elementsPerBlock;
        uint32_t endIdx = (startIdx + elementsPerBlock > totalLength) ? totalLength : startIdx + elementsPerBlock;
        uint32_t curCount = endIdx - startIdx;
        uint32_t fullTiles = curCount / TILE_LENGTH;
        uint32_t tailLength = curCount % TILE_LENGTH;
        uint32_t loopCount = fullTiles + (tailLength > 0 ? 1 : 0);
        for (uint32_t i = 0; i < loopCount; i++) {
            uint32_t curLength = (i < fullTiles) ? TILE_LENGTH : tailLength;
            uint32_t alignedLen = ALIGN_NUM * ((curLength + ALIGN_NUM - 1) / ALIGN_NUM);
            CopyIn(startIdx + i * TILE_LENGTH, alignedLen);
            Compute(alignedLen);
            CopyOut(startIdx + i * TILE_LENGTH, alignedLen);
        }
    }

private:
    __aicore__ inline void CopyIn(uint32_t offset, uint32_t length)
    {
        LocalTensor<half> xLocal = inQueueX.AllocTensor<half>();
        DataCopy(xLocal, xGm[offset], length);
        inQueueX.EnQue(xLocal);
    }
    __aicore__ inline void Compute(uint32_t length)
    {
        LocalTensor<half> xLocal = inQueueX.DeQue<half>();
        LocalTensor<half> yLocal = outQueueY.AllocTensor<half>();
        LocalTensor<float> xFloat = xFloatBuf.Get<float>();
        LocalTensor<float> tmpFloat = tmpBuf.Get<float>();
        LocalTensor<float> yFloat = yFloatBuf.Get<float>();
        Cast(xFloat, xLocal, RoundMode::CAST_NONE, length);
        Muls(tmpFloat, xFloat, scale, length);
        Adds(tmpFloat, tmpFloat, bias, length);
        Maxs(yFloat, tmpFloat, minVal, length);
        Mins(yFloat, yFloat, maxVal, length);
        Cast(yLocal, yFloat, RoundMode::CAST_NONE, length);
        outQueueY.EnQue<half>(yLocal);
        inQueueX.FreeTensor(xLocal);
    }
    __aicore__ inline void CopyOut(uint32_t offset, uint32_t length)
    {
        LocalTensor<half> yLocal = outQueueY.DeQue<half>();
        DataCopy(yGm[offset], yLocal, length);
        outQueueY.FreeTensor(yLocal);
    }

private:
    TPipe pipe;
    TQue<TPosition::VECIN, BUFFER_NUM> inQueueX;
    TQue<TPosition::VECOUT, BUFFER_NUM> outQueueY;
    TBuf<TPosition::VECCALC> xFloatBuf;
    TBuf<TPosition::VECCALC> tmpBuf;
    TBuf<TPosition::VECCALC> yFloatBuf;
    GlobalTensor<half> xGm;
    GlobalTensor<half> yGm;
    uint32_t totalLength;
    float scale;
    float bias;
    float minVal;
    float maxVal;
};

extern "C" __global__ __aicore__ void pixel_scale_clip_custom(GM_ADDR x, GM_ADDR y,
                                                             uint32_t totalLength,
                                                             float scale, float bias,
                                                             float minVal, float maxVal)
{
    KernelPixelScaleClip op;
    op.Init(x, y, totalLength, scale, bias, minVal, maxVal);
    op.Process();
}

#include <ATen/ATen.h>
#include <torch/library.h>

struct aclmdlRITask;
struct aclmdlRITaskParams;

#include <acl/acl.h>
#include "torch_npu/csrc/core/npu/NPUStream.h"
#include "aclrtlaunch_pixel_scale_clip_custom.h"

namespace ascendc_path {

at::Tensor run_pixel_scale_clip_custom(const at::Tensor &x, double scale, double bias,
                                       double minVal, double maxVal)
{
    at::Tensor y = at::empty_like(x);
    uint32_t blockDim = 8;
    uint32_t totalLength = 1;
    for (uint32_t size : x.sizes()) {
        totalLength *= size;
    }
    float fScale = (float)scale, fBias = (float)bias, fMinVal = (float)minVal, fMaxVal = (float)maxVal;
    auto stream = c10_npu::getCurrentNPUStream();
    aclrtlaunch_pixel_scale_clip_custom(blockDim, stream,
        const_cast<void*>(x.storage().data()), const_cast<void*>(y.storage().data()),
        totalLength, fScale, fBias, fMinVal, fMaxVal);
    return y;
}
} // namespace ascendc_path

namespace {
TORCH_LIBRARY_FRAGMENT(npu, m)
{
    m.def("my_pixel_scale_clip(Tensor x, float scale, float bias, float min_val, float max_val) -> Tensor");
}
}

namespace {
TORCH_LIBRARY_IMPL(npu, PrivateUse1, m)
{
    m.impl("my_pixel_scale_clip", TORCH_FN(ascendc_path::run_pixel_scale_clip_custom));
}
}
